    const pressOpenAnalysis = async (doc = document) => {
        // A click on the button just before this call may not have rendered the menu yet: give it a moment before clicking (a second click would shut it).
        if (!(await waitFor(() => !!doc.querySelector('[data-analyze-menu]'), { timeout: 400 }))) { const b = doc.querySelector('[data-analyze-button]'); if (!b || b.disabled) return false; b.click(); }
        if (!(await waitFor(() => !!doc.querySelector('[data-analyze-open]'), { timeout: 5000 }))) return false;
        const item = doc.querySelector('[data-analyze-open]');
        if (item.disabled) return false;
        item.click();
        return true;
    };
