        const LABEL = `${isPol ? 'POL Booking Flash' : 'Booking Flash'}: one border weight and colour everywhere (D73): every body column's right border, and the header cells' own line, is 1px solid rgb(156, 163, 175) with no heavy 2px lines, and the scroll box is 1px rgb(156, 163, 175) on all four sides`;
