                                const seen = {};
                                const one = (s) => (s.tags === null) !== (s.hint === null);   // exactly one of the two
                                seen.noVvd = draftState();
                                await setVvd(N1.vvd);
                                seen.emptyDraft = { ...draftState(), draft: taEl().value, placeholder: taEl().getAttribute('placeholder') };
