                                    const n1Btns = btnsOf(N1);
                                    const longBtn = btnsOf(NL)[0], longHolder = holderOf(NL), panel = dlg();
                                    const lb = longBtn && longBtn.getBoundingClientRect(), lh = longHolder && longHolder.getBoundingClientRect();
