            // A mouse event at a point, sent to whatever the page hit-tests there (as a real pointer would be).
            const fireAt = (type, p, extra = {}) => {
                const el = hitAt(p);
                const ev = new a.win.MouseEvent(type, { bubbles: true, cancelable: true, view: a.win, clientX: p.x, clientY: p.y, button: type === 'contextmenu' ? 2 : 0, ...extra });
                if (el) el.dispatchEvent(ev);
                return { el, ev };
            };
            const rowOf = () => S.btn.closest('tr');
            const vvdSpan = () => S.btn.closest('td').querySelector('[data-gmail-search]');
